#!/usr/bin/env node
import { chmodSync, cpSync, mkdirSync, readFileSync, readdirSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { applyStamps } from './stamp.mjs';

export const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
export const ADAPTERS = ['claude-code', 'codex', 'universal'];
export const GENERATED_BANNER =
  '<!-- GENERATED by lua-agent-kit (build/emit.mjs). Do not edit here: change the source in lua-agent-kit and re-emit. -->\n';

export function rootVersion() {
  return JSON.parse(readFileSync(join(ROOT, 'package.json'), 'utf8')).version;
}

function walk(abs, rel, exclude, out) {
  const st = statSync(abs);
  if (!st.isDirectory()) {
    out.push({ abs, rel, mode: st.mode & 0o777 });
    return out;
  }
  for (const entry of readdirSync(abs).sort()) {
    if (exclude.includes(entry)) continue;
    walk(join(abs, entry), rel ? `${rel}/${entry}` : entry, exclude, out);
  }
  return out;
}

function addFile(files, path, file) {
  const key = path.replace(/^\.\//, '');
  if (files.has(key)) throw new Error(`emit: two sources write ${key}: ${files.get(key).source} and ${file.source}`);
  files.set(key, file);
}

export function collectMounts(mounts, files = new Map()) {
  for (const mount of mounts) {
    for (const file of walk(join(ROOT, mount.from), '', mount.exclude ?? [], [])) {
      const dest = file.rel ? `${mount.to}/${file.rel}` : mount.to;
      addFile(files, dest, { content: readFileSync(file.abs), mode: file.mode, source: file.abs });
    }
  }
  return files;
}

export async function loadAdapter(name) {
  return import(pathToFileURL(join(ROOT, 'adapters', name, 'adapter.mjs')).href);
}

export async function buildTree(name, version = rootVersion()) {
  const adapter = await loadAdapter(name);
  const ctx = { root: ROOT, version };
  const files = collectMounts(adapter.mounts);
  for (const out of adapter.generate(ctx)) {
    addFile(files, out.path, { content: Buffer.from(out.content, 'utf8'), mode: out.mode ?? 0o644, source: `generated:${out.path}` });
  }
  applyStamps(files, adapter.stamps ?? [], version);
  for (const path of adapter.banner ?? []) {
    const file = files.get(path);
    files.set(path, { ...file, content: Buffer.concat([Buffer.from(GENERATED_BANNER), file.content]) });
  }
  return files;
}

export async function emit(name, outDir, version) {
  const files = await buildTree(name, version);
  rmSync(outDir, { recursive: true, force: true });
  for (const [rel, file] of files) {
    const dest = join(outDir, rel);
    mkdirSync(dirname(dest), { recursive: true });
    writeFileSync(dest, file.content);
    chmodSync(dest, file.mode);
  }
  return files.size;
}

function parseArgs(argv) {
  const args = { adapters: [], out: null, version: undefined };
  const flags = {
    '--all': () => { args.adapters = [...ADAPTERS]; return 0; },
    '--adapter': (v) => { args.adapters.push(v); return 1; },
    '--out': (v) => { args.out = v; return 1; },
    '--version': (v) => { args.version = v; return 1; },
  };
  for (let i = 0; i < argv.length; i += 1) {
    const flag = flags[argv[i]];
    if (!flag) throw new Error(`emit: unknown argument ${argv[i]}`);
    i += flag(argv[i + 1]);
  }
  if (args.adapters.length === 0) args.adapters = [...ADAPTERS];
  return args;
}

async function mirror(name, outDir) {
  const adapter = await loadAdapter(name);
  for (const m of adapter.mirrors ?? []) {
    const dest = join(ROOT, m.to);
    rmSync(dest, { recursive: true, force: true });
    cpSync(join(outDir, m.from), dest, { recursive: true });
    process.stdout.write(`emit: ${name} mirrored ${m.from} -> ${m.to}\n`);
  }
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  for (const name of args.adapters) {
    const custom = args.out && args.adapters.length === 1;
    const outDir = custom ? resolve(args.out) : join(ROOT, 'dist', name);
    const count = await emit(name, outDir, args.version);
    process.stdout.write(`emit: ${name} -> ${outDir} (${count} files)\n`);
    if (!custom) await mirror(name, outDir);
  }
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  main().catch((err) => {
    process.stderr.write(`${err.message}\n`);
    process.exit(1);
  });
}
